## ---- 01: Build Asset Data and Project Cashflows via `oasr`  (qmd line 251) -----------

library(oasr)

# asset_data structure expected by oasr: balance, wac, term, servicing
# (io_strip is additionally required by project_cashflows_with_io)
asset_data <- data.frame(
  asset_id  = "LOAN_001",
  balance   = 1e6,       # current balance ($)
  wac       = 0.085,     # gross coupon
  term      = 300,       # original term (months)
  age       = 0,         # seasoning (months)
  servicing = 0.01,      # servicing spread
  io_strip  = 0.0055     # guaranty / excess-IO strip spread
)

# Define a prepayment/credit model
prepay_mod <- prepayment_model(type = "cpr_cdr",
                                base_cpr = 0.06, base_cdr = 0.01,
                                recovery_rate = 0.65)

# simulate_rates() takes calibrated DNS parameters (Chapters 3-6) and
# returns rate paths as a named list per maturity ($yield_paths).
# Its maturities default to years, so lambda is per year (Chapter 2).
dns_params <- list(
  params = list(kappa = c(0.3, 0.5, 0.8),
                theta = c(0.04, -0.01, 0.01),
                sigma = c(0.010, 0.012, 0.015)),
  initial_factors = c(0.035, -0.015, 0.005),
  lambda = 0.7308
)
rate_paths <- simulate_rates(dns_params, n_paths = 1,
                              n_periods = 360, seed = 42)

# Step 1: derive credit vectors (CPR/CDR per path/period)
credit_v <- calculate_credit_vectors(asset_data, rate_paths, prepay_mod)

# Step 2: project loan-level cashflows; reference_rates is the
# [n_paths x n_periods] matrix for the reference maturity
ref_rates <- extract_reference_rates(rate_paths)
cf <- project_cashflows(asset_data, credit_v,
                         reference_rates = ref_rates)
str(cf)


## ---- 02: Whole-Loan vs IO Cashflow with `project_cashflows_with_io`  (qmd line 297) --

# Materialize whole-loan + IO components in a single call
cf_io <- project_cashflows_with_io(asset_data, credit_v,
                                    reference_rates = ref_rates)
# cf_io contains additional IO-strip cashflow component


## ---- 03: Balance Identity Check (User Helper)  (qmd line 306) ------------------------

# Helper: validate balance recursion on the projected cashflows.
# oasr cashflow columns: 1 = ending balance, 2 = scheduled principal,
# 3 = voluntary prepay, 4 = default.
# Identity: B_{t+1} = B_t - P_t - VP_t - D_t
check_balance_identity <- function(cf_mat, B0) {
  B_end   <- cf_mat[, 1]
  B_begin <- c(B0, B_end[-length(B_end)])
  err <- B_end - (B_begin - cf_mat[, 2] - cf_mat[, 3] - cf_mat[, 4])
  max(abs(err))
}

check_balance_identity(cf[[1]][, , 1], asset_data$balance[1])


## ---- 04: Pool-Level Aggregation via `oasr::aggregate_cashflows`  (qmd line 323) ------

# Build a multi-loan pool
set.seed(42)
n_loans <- 100
pool_assets <- data.frame(
  asset_id  = sprintf("LOAN_%03d", seq_len(n_loans)),
  balance   = runif(n_loans, 5e4, 5e5),
  wac       = runif(n_loans, 0.065, 0.105),
  term      = sample(c(120, 180, 240, 300), n_loans, replace = TRUE),
  age       = sample(0:60, n_loans, replace = TRUE),
  servicing = 0.01,
  io_strip  = 0.0055
)

# Two-tranche deal: senior/sub with sequential principal
deal <- list(
  bonds = data.frame(bond_id = c("A", "B"),
                     balance = c(0.9, 0.1) * sum(pool_assets$balance),
                     coupon  = c(0.055, 0.075)),
  waterfall = list(principal = "sequential",
                   interest  = "pro_rata",
                   losses    = "reverse_sequential")
)

credit_v    <- calculate_credit_vectors(pool_assets, rate_paths, prepay_mod)
loan_cfs    <- project_cashflows(pool_assets, credit_v,
                                  reference_rates = ref_rates,
                                  parallel = TRUE)
pool_cf     <- aggregate_cashflows(loan_cfs, pool_assets, deal)

# pool_cf is a per-path list of tranche-level cashflow arrays
str(pool_cf, max.level = 1)


## ---- 05: Average Life  (qmd line 359) ------------------------------------------------

# oasr::calculate_average_life produces WAL of the aggregated cashflows
# (in the tranche-level arrays, column 2 holds principal)
wal <- calculate_average_life(pool_cf, asset_level = FALSE,
                              principal_idx = 2)
wal


